<?php require '../includes/auth.php';require_role('admin');$rows=db()->query('SELECT r.*,u.name reporter,p.name product FROM reports r JOIN users u ON u.id=r.reporter_id LEFT JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC')->fetchAll();$pageTitle='Reports';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ADMIN</p><h1>Reports</h1></div><div class="table-wrap"><table><thead><tr><th>Reporter</th><th>Product</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reporter'])?></td><td><?=e($r['product']??'User report')?></td><td><?=e($r['reason'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty"><h2>No reports right now.</h2></div><?php endif;require '../includes/footer.php'; ?>
